<?php require_once 'bootstrap.php';$u=require_admin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$amount=max(0,(float)($_POST['amount']??0));if($amount>0){vault_community_allocate($amount,'DAO_TREASURY_ALLOCATION',$u['sic_id']);$msg='Allocazione Community registrata.';}}vault_reserve_sync();$reserve=vault_pool_balance('RESERVE');$community=vault_pool_balance('COMMUNITY');$pageTitle='Vault Admin';require '_header.php';?><section class="section-head"><div><span class="eyebrow">DRX Vault Control</span><h1>Vault Admin</h1><p>Blockchain disattivata: questa è contabilità interna/audit-ready.</p></div></section><?php if($msg):?><div class="success"><?=h($msg)?></div><?php endif;?><section class="metric-grid"><div class="metric"><b><?=number_format($reserve,0,',','.')?></b><span>Reserve</span></div><div class="metric"><b><?=number_format($community,0,',','.')?></b><span>Community</span></div></section><section class="card"><h2>Allocazione DAO/Tesoreria al Community Pool</h2><form method="post" class="stack"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><input type="number" step="1" min="1" name="amount" placeholder="DRX" required><button class="btn primary">Alloca</button></form></section><?php require '_footer.php';?>